import json
import re
from docx import Document

TEMPLATE = 'offer_letter_template.docx'
DATA_PATH = 'employee_data.json'
OUTPUT = '/root/offer_letter_filled.docx'

with open(DATA_PATH, 'r', encoding='utf-8') as f:
    data = json.load(f)

doc = Document(TEMPLATE)

pattern = re.compile(r'\{\{([A-Z_]+)\}\}')

def set_paragraph_text(para, text):
    if para.runs:
        para.runs[0].text = text
        for run in para.runs[1:]:
            run.text = ''
    else:
        para.add_run(text)


def handle_conditional(paragraphs, condition_key, include):
    start_marker = f'{{{{IF_{condition_key}}}}}'
    end_marker = f'{{{{END_IF_{condition_key}}}}}'
    in_block = False
    for para in paragraphs:
        text = para.text
        if start_marker in text and end_marker in text:
            if include:
                new_text = text.replace(start_marker, '').replace(end_marker, '')
            else:
                start = text.find(start_marker)
                end = text.find(end_marker) + len(end_marker)
                new_text = text[:start] + text[end:]
            set_paragraph_text(para, new_text)
            continue
        if start_marker in text:
            in_block = True
            if include:
                new_text = text.replace(start_marker, '')
            else:
                new_text = text.split(start_marker, 1)[0]
            set_paragraph_text(para, new_text)
            continue
        if end_marker in text:
            if include:
                new_text = text.replace(end_marker, '')
            else:
                new_text = text.split(end_marker, 1)[1]
            set_paragraph_text(para, new_text)
            in_block = False
            continue
        if in_block and not include:
            set_paragraph_text(para, '')


def replace_in_paragraph(para):
    text = para.text
    if not pattern.search(text):
        return
    def repl(match):
        key = match.group(1)
        return str(data.get(key, match.group(0)))
    new_text = pattern.sub(repl, text)
    if new_text != text:
        set_paragraph_text(para, new_text)


def process_table(table):
    for row in table.rows:
        for cell in row.cells:
            # Conditionals within cell
            handle_conditional(cell.paragraphs, 'RELOCATION', include_relocation)
            for para in cell.paragraphs:
                replace_in_paragraph(para)
            for nested in cell.tables:
                process_table(nested)

include_relocation = str(data.get('RELOCATION_PACKAGE', '')).strip().lower() == 'yes'

# Handle conditionals in main body
handle_conditional(doc.paragraphs, 'RELOCATION', include_relocation)

# Replace placeholders in main body
for para in doc.paragraphs:
    replace_in_paragraph(para)

# Tables (with nesting)
for table in doc.tables:
    process_table(table)

# Headers and footers
for section in doc.sections:
    handle_conditional(section.header.paragraphs, 'RELOCATION', include_relocation)
    for para in section.header.paragraphs:
        replace_in_paragraph(para)

    handle_conditional(section.footer.paragraphs, 'RELOCATION', include_relocation)
    for para in section.footer.paragraphs:
        replace_in_paragraph(para)

doc.save(OUTPUT)
print('Saved to', OUTPUT)
